public class Base62 {
    private static final String ALPHABET =
            "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";

    public static String encode(long value) {
        if (value == 0) {
            return "0";
        }
        StringBuilder result = new StringBuilder();
        while (value > 0) {
            result.append(ALPHABET.charAt((int) (value % 62)));
            value /= 62;
        }
        return result.reverse().toString();
    }
}

public class TokenBucket {
    private final double refillPerSecond;
    private final double capacity;
    private double tokens;
    private long lastRefillNanos;

    public TokenBucket(double refillPerSecond, double capacity) {
        this.refillPerSecond = refillPerSecond;
        this.capacity = capacity;
        this.tokens = capacity;
        this.lastRefillNanos = System.nanoTime();
    }

    public synchronized boolean tryAcquire() {
        refill();
        if (tokens >= 1) {
            tokens -= 1;
            return true;
        }
        return false;
    }

    private void refill() {
        long now = System.nanoTime();
        double added = (now - lastRefillNanos) / 1_000_000_000.0 * refillPerSecond;
        tokens = Math.min(capacity, tokens + added);
        lastRefillNanos = now;
    }
}

import java.util.*;

public class ExpenseSplitter {
    private final Map<String, Double> balances = new HashMap<>();

    public void addExpense(String paidBy, double amount, List<String> participants) {
        double share = amount / participants.size();
        balances.merge(paidBy, amount, Double::sum);
        for (String participant : participants) {
            balances.merge(participant, -share, Double::sum);
        }
    }

    public double balanceOf(String user) {
        return balances.getOrDefault(user, 0.0);
    }
}
